INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (18, 12, 'theory', 'Quiz: news feed');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 0, 'What is the main drawback of the pull scheme (building the feed on read)?', '["Expensive writes", "Heavy reads: dozens of queries on every feed open", "Replicas are needed", "It can''t be cached"]', 1, 'Read load grows with the number of follows, while writes are cheap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 1, 'Why does push work badly for celebrities?', '["They write too rarely", "One post produces millions of writes into followers'' feeds", "Celebrities don''t use feeds", "Push doesn''t use a cache"]', 1, 'Fanning out to millions of followers causes a load spike and a publishing delay.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 2, 'What does the hybrid approach do?', '["Uses only pull", "Fans out ordinary authors'' posts and mixes in celebrity posts at read time", "Uses only push", "Doesn''t store posts"]', 1, 'Writes stay cheap, and reads add only a few fresh celebrity posts.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 3, 'What does a user''s ready feed store?', '["Whole post texts", "Post identifiers", "Images", "Passwords"]', 1, 'This saves memory, and editing a post doesn''t require updating thousands of feeds; pagination is by cursor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (18, 12, 4, 'How are inactive users'' feeds handled?', '["Updated every second", "Not maintained: the entry expires and the feed is built on return", "Accounts are deleted", "Encrypted"]', 1, 'This sharply cuts fan-out work; only the rare return is slower.');
